	CONSTRAINT "workspace_pricing_revision_check" CHECK ("workspace_pricing_settings"."revision" > 0)
);

ALTER TABLE "public"."workspace_pricing_settings" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."addresses" ADD COLUMN "pricing_currency" varchar(3);
ALTER TABLE "public"."workspace_pricing_settings" ADD CONSTRAINT "workspace_pricing_settings_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "public"."workspace_pricing_settings" ADD CONSTRAINT "workspace_pricing_settings_company_id_companies_id_fk" FOREIGN KEY ("company_id") REFERENCES "public"."companies"("id") ON DELETE cascade ON UPDATE no action;
CREATE UNIQUE INDEX "workspace_pricing_personal_identity" ON "public"."workspace_pricing_settings" USING btree ("user_id");
CREATE UNIQUE INDEX "workspace_pricing_company_identity" ON "public"."workspace_pricing_settings" USING btree ("company_id");
ALTER TABLE "public"."addresses" ADD CONSTRAINT "addresses_pricing_currency_check" CHECK ("addresses"."pricing_currency" IS NULL OR "addresses"."pricing_currency" IN ('AED', 'AFN', 'ALL', 'AMD', 'AOA', 'ARS', 'AUD', 'AWG', 'AZN', 'BAM', 'BBD', 'BDT', 'BHD', 'BIF', 'BMD', 'BND', 'BOB', 'BRL', 'BSD', 'BTN', 'BWP', 'BYN', 'BZD', 'CAD', 'CDF', 'CHF', 'CLP', 'CNY', 'COP', 'CRC', 'CUP', 'CVE', 'CZK', 'DJF', 'DKK', 'DOP', 'DZD', 'EGP', 'ERN', 'ETB', 'EUR', 'FJD', 'FKP', 'GBP', 'GEL', 'GHS', 'GIP', 'GMD', 'GNF', 'GTQ', 'GYD', 'HKD', 'HNL', 'HTG', 'HUF', 'IDR', 'ILS', 'INR', 'IQD', 'IRR', 'ISK', 'JMD', 'JOD', 'JPY', 'KES', 'KGS', 'KHR', 'KMF', 'KPW', 'KRW', 'KWD', 'KYD', 'KZT', 'LAK', 'LBP', 'LKR', 'LRD', 'LSL', 'LYD', 'MAD', 'MDL', 'MGA', 'MKD', 'MMK', 'MNT', 'MOP', 'MRU', 'MUR', 'MVR', 'MWK', 'MXN', 'MYR', 'MZN', 'NAD', 'NGN', 'NIO', 'NOK', 'NPR', 'NZD', 'OMR', 'PAB', 'PEN', 'PGK', 'PHP', 'PKR', 'PLN', 'PYG', 'QAR', 'RON', 'RSD', 'RUB', 'RWF', 'SAR', 'SBD', 'SCR', 'SDG', 'SEK', 'SGD', 'SHP', 'SLE', 'SOS', 'SRD', 'SSP', 'STN', 'SYP', 'SZL', 'THB', 'TJS', 'TMT', 'TND', 'TOP', 'TRY', 'TTD', 'TWD', 'TZS', 'UAH', 'UGX', 'USD', 'UYU', 'UZS', 'VES', 'VND', 'VUV', 'WST', 'XAF', 'XCD', 'XCG', 'XOF', 'XPF', 'YER', 'ZAR', 'ZMW', 'ZWG'));
-- END GENERATED WORKSPACE PRICING DDL
REVOKE ALL ON TABLE public.workspace_pricing_settings FROM PUBLIC, anon, authenticated, service_role, fm_app_runtime, fmt_app_dev, fmt_audit_capture_dev, fmt_audit_worker_dev;
GRANT SELECT,INSERT,UPDATE ON TABLE public.workspace_pricing_settings TO fm_app_runtime;
CREATE POLICY fmt_workspace_pricing_server ON public.workspace_pricing_settings FOR ALL TO fm_app_runtime USING(true) WITH CHECK(true);
-- Existing workspace defaults only: no service/booking currency or amount UPDATE.
INSERT INTO public.workspace_pricing_settings(id,user_id,default_currency,revision)
 SELECT gen_random_uuid(),id,'EUR',1 FROM public.users;
INSERT INTO public.workspace_pricing_settings(id,company_id,default_currency,revision)
 SELECT gen_random_uuid(),id,'EUR',1 FROM public.companies;
SELECT (SELECT count(*) FROM public.workspace_pricing_settings WHERE user_id IS NOT NULL) AS personal_defaults_initialized,
 (SELECT count(*) FROM public.workspace_pricing_settings WHERE company_id IS NOT NULL) AS company_defaults_initialized;
COMMIT;
